function combinationTotals(candidates, target) {
  const sorted = [...candidates].sort((a, b) => a - b)
  const results = []
  const path = []
  const explore = (start, remaining) => {
    if (remaining === 0) { results.push([...path]); return }
    for (let i = start; i < sorted.length && sorted[i] <= remaining; i++) {
      path.push(sorted[i])
      explore(i, remaining - sorted[i])
      path.pop()
    }
  }
  explore(0, target)
  return results
}

