def combination_totals(candidates, target):
    ordered = sorted(candidates)
    results, path = [], []

    def explore(start, remaining):
        if remaining == 0:
            results.append(path[:])
            return
        for i in range(start, len(ordered)):
            if ordered[i] > remaining:
                break
            path.append(ordered[i])
            explore(i, remaining - ordered[i])
            path.pop()

    explore(0, target)
    return results
